// === Tab: butterflyShader ===
var vert=`
  attribute vec3 aPosition;
attribute vec3 aNormal;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

varying vec3 vVertexNormal;
varying highp vec2 vVertTexCoord;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
  vVertexNormal = normalize(vec3( uNormalMatrix * aNormal ));
  vVertTexCoord = aTexCoord;
}
`;
var frag=`
  #ifdef GL_ES
  precision highp float;
#endif
  uniform float iGlobalTime;
uniform vec2 iResolution;
uniform float ncol;
uniform float nrang;
const int noctaves=3;
const mat2 rot = mat2( 0.80, 0.6, -0.6, 0.8 );
float nb;

float butterfly(float r, float t,float nh) {
  float b = 
    7.2- (3.0*nh+.5)*sin(t) + 2.5*sin(3.*t) + 2.*sin(5.*t) - 1.7*sin(7.*t)*nh +
    (2.0*nh+3.)*cos(2.*t) - (2.0*nh+3.)*cos(4.*t) - (1.5*nh-0.8)*cos(16.*t) - r;
  return b;
}

float hash(vec2 z)
{
  return fract(sin(dot(z, vec2(12.9898, 78.233))) * 43758.5453);
}
float noise( in vec2 x,float nh )
{
  return sin(2.5*x.x)*sin(1.5*x.y-5.0*iGlobalTime*nh);
}
float fbm ( in vec2 _st, float n) {
  float v =n;
  float a = n;
  for (int i = 0; i < 12; ++i) {//noprotect
    if (i>=noctaves)break;
    v += a * noise(_st,.5*hash(vec2(n, n)));
    _st = (1.50+.02*n)*(rot*_st) ;
    a *= 1.65+.02*n;
  }
  return n/v;
}

void main(void)
{   
  vec3 col = vec3(0.0);
  vec2 st=gl_FragCoord.xy/iResolution;
  nb=5.0+(float(int(st.x*ncol))+nrang*float(int(st.y*nrang)));
  float nh=hash(vec2(nb, nb+ncol));
  vec2 bpos=vec2(((1.0)/sin(10.0*nh*(iGlobalTime+.4*st.y)/(1.0+nh)))*(.5*ncol*mod(st.x, 1.0/ncol)-.25), .5*nrang*mod(st.y, 1.0/nrang)-.25);  
  float angle=atan(bpos.y, bpos.x);
  float rayon=.02*abs(butterfly(length(bpos), angle,nh));
	float heart=smoothstep(.031,.03,length(vec2(bpos.x,bpos.y-0.15*sqrt(abs(bpos.x)))));
  float r=heart+fbm(nb+.6*abs(4.0*bpos)-3.0*abs(cos(.01*iGlobalTime)), nb);
  float g=fbm(1.2*abs(4.35*bpos)+.5*nb, .2*nb);
  float b=fbm(1.3*abs(bpos*4.25), 3.0*nh+nb);//.2*sin(-.1*iGlobalTime+bpos.x)+
  if (length(bpos)<rayon)col=vec3(clamp(r,0.2,1.0),clamp(g,0.0,1.0), clamp(mix(b, g, 2.5+nb/nh),.0,1.0))+.1*mix(r, b, 5.0*nh);//, mix(g, r, 7.0*nh)
  gl_FragColor = vec4(col, 1.0);
}
`;

